def test_timer_can_be_started_after_context_manager():
    """Test that a Timer can be started after being used as a context manager."""
    # Create a timer instance
    timer_instance = timer.Timer()
    
    # Use timer as context manager (starts on enter, stops on exit)
    context_timer = timer_instance.__enter__()
    exit_result = timer_instance.__exit__(None, None, None)
    
    # Start the timer after context manager has exited
    start_result = context_timer.start()
    
    # Start the same timer again (should raise error if already running)
    timer_instance.start()

